// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MarkerDrawingProps = Record<string, any>;

const MarkerDrawing: React.FC<MarkerDrawingProps> = ({
  backgroundColor = "#F7F7F7",
  transparentBackground = false,
  durationInSeconds = 5,
  inkColor = "#111111",
  circleRadius = 300,
  strokeWidth = 14,
  centerText = "Malloy Studio",
  textColor = "#111111",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Playfair Display"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout calculations
  const cx = width / 2;
  const cy = height / 2;
  
  // Transform the radius into an oval shape
  const rx = circleRadius * 1.5;
  const ry = circleRadius * 0.8;

  // Path Generation (Memoized for performance)
  const path = React.useMemo(
    () =>
      `M ${cx} ${cy - ry} A ${rx} ${ry} 0 0 1 ${cx} ${cy + ry} A ${rx} ${ry} 0 0 1 ${cx} ${cy - ry}`,
    [cx, cy, rx, ry]
  );

  // Timing logic
  const totalFrames = durationInSeconds * fps;
  const flyInFrames = Math.max(1, Math.min(fps, totalFrames * 0.2)); 
  const flyOutFrames = Math.max(1, Math.min(fps, totalFrames * 0.2)); 
  const drawFrames = Math.max(1, totalFrames - flyInFrames - flyOutFrames);

  // Safely interpolate drawing progress
  const drawProgress = interpolate(
    frame,
    [flyInFrames, flyInFrames + drawFrames],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.sin), 
    }
  );

  const evolution = evolvePath(drawProgress, path);

  // Text appearance animations
  const textOpacity = interpolate(drawProgress, [0.6, 0.9], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const textScaleAnim = interpolate(drawProgress, [0.6, 0.9], [0.8, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Playfair Display", transition: "none" }}>
      
      {/* Background Center Text */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: textOpacity,
          transform: `scale(${textScaleAnim})`,
          pointerEvents: "none",
          zIndex: 1,
          transition: "none",
        }}
      >
        <span
          style={{
            fontSize: `${circleRadius * 0.35}px`,
            fontWeight: 700,
            color: textColor,
            textAlign: "center",
            maxWidth: rx * 1.8,
            lineHeight: 1.1,
            transition: "none",
          }}
        >
          {centerText}
        </span>
      </div>

      {/* Drawn Ink Oval */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          zIndex: 5,
          transition: "none",
        }}
      >
        <path
          d={path}
          stroke={inkColor}
          strokeWidth={strokeWidth}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          style={{ transition: "none" }}
        />
      </svg>
      
    </AbsoluteFill>
  );
};

export default MarkerDrawing;